=== VITE ===
import { fileURLToPath, URL } from 'node:url'
import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'
import Icons from 'unplugin-icons/vite'
import IconsResolver from 'unplugin-icons/resolver'
import mkcert from 'vite-plugin-mkcert'
import Components from 'unplugin-vue-components/vite'
import { BootstrapVueNextResolver } from 'bootstrap-vue-next/resolvers'
// https://vitejs.dev/config/
export default defineConfig({
  plugins: [
    vue(),
    mkcert(),
    Components({
      resolvers: [
        BootstrapVueNextResolver(), // Resuelve componentes de BootstrapVueNext
        IconsResolver()
      ],
      dts: true,
    }),
    Icons({
      compiler: 'vue3',
      autoInstall: true,
    }),
  ],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url))
    }
  },
  server: {
    // El backend web2py de desarrollo usa un certificado autofirmado que el
    // navegador rechaza. Con este proxy el navegador solo habla con el dev
    // server (mkcert) y es Vite quien se conecta a web2py ignorando su
    // certificado (`secure: false`). Requiere VITE_API_URL="/admred" en
    // .env.local; ademA�s deja las peticiones en el mismo origen (sin CORS).
    proxy: {
      '/admred': {
        target: 'https://localhost:8000',
        changeOrigin: true,
        secure: false,
      },
    },
  },
  optimizeDeps: {
    noDiscovery: true,
    include: undefined
  },
});
=== ENV ===
.env: VITE_API_URL="https://localhost:8000/admred"
.env.corp: VITE_API_URL="https://172.17.48.90:8000/admred"
.env.local: # ConfiguraciA3n local para probar contra el backend sin el problema de su
# certificado autofirmado: las peticiones van al proxy de Vite (ver
# vite.config.js), que las reenvA-a a https://localhost:8000.
VITE_API_URL="/admred"

.env.production: VITE_API_URL="/admred"

import { createRouter, createWebHashHistory } from 'vue-router'
import type { RouteRecordRaw } from 'vue-router'
import { useAuthQuery, useLogout } from '@/stores/auth'
import { until } from '@vueuse/core'
import { useStorage } from '@vueuse/core'

/** Normaliza un parA�metro de ruta a id numAcrico (vue-router lo tipa `string | string[]`). */
const idDeRuta = (valor: string | string[] | undefined) => parseInt(String(valor))

/** Normaliza un valor de `query` a texto. */
const textoDeQuery = (valor: string | string[] | undefined) => String(valor ?? '')

const folderDefault = () => {  const folders = [
    'recibidas/pendientes',
    'recibidas/terminadas',
    'enviadas/pendientes',
    'enviadas/terminadas'
  ]
  const folder = useStorage('admred_router_folder', 'enviadas/pendientes')
  return folders.includes(folder.value)
    ? `/solicitudes/${folder.value}`
    : '/solicitudes/enviadas/pendientes'
}

const rutasSolicitud = (rutaBase: string, rutaPadre: string, prefijo?: string): RouteRecordRaw => {
  return {
    path: prefijo ? prefijo + '/:solicitudId' : ':solicitudId',
    name: rutaBase,
    component: () => import('@/views/solicitudes/[id]/index.vue'),
    props: route => ({
      solicitudId: idDeRuta(route.params.solicitudId),
      linkSolicitud: (solicitudId) => ({ params: { solicitudId } }),
      setSolicitudId: (solicitudId) => router.push({ params: { solicitudId } }),
      back: () => router.push({ name: rutaPadre }),
      rutaBase
    }),
    children: [
      {
        path: 'asignar',
        name: rutaBase + '-asignar',
        component: () => import('@/views/solicitudes/[id]/asignar.vue'),
        props: route => ({
          solicitudId: idDeRuta(route.params.solicitudId),
          back: () => router.push({ name: rutaBase })
        })
      },
      {
        path: 'reenviar',
        name: rutaBase + '-reenviar',
        component: () => import('@/views/solicitudes/[id]/reenviar.vue'),
        props: route => ({
          solicitudId: idDeRuta(route.params.solicitudId),
          back: () => router.push({ name: rutaBase })
        })
      },
      {
        path: 'responder',
        name: rutaBase + '-responder',
        component: () => import('@/views/solicitudes/[id]/responder.vue'),
        props: route => ({
          solicitudId: idDeRuta(route.params.solicitudId),
          back: () => router.push({ name: rutaBase })
        })
      },
      {
        path: 'aprobar',
        name: rutaBase + '-aprobar',
        component: () => import('@/views/solicitudes/[id]/aprobar.vue'),
        props: route => ({
          solicitudId: idDeRuta(route.params.solicitudId),
          back: () => router.push({ name: rutaBase })
        })
      },
      {
        path: 'evaluar',
        name: rutaBase + '-evaluar',
        component: () => import('@/views/solicitudes/[id]/evaluar.vue'),
        props: route => ({
          solicitudId: idDeRuta(route.params.solicitudId),
          back: () => router.push({ name: rutaBase })
        })
      },
      {
        path: 'registro',
        name: rutaBase + '-registro',
        component: () => import('@/views/solicitudes/[id]/registro.vue'),
        props: route => ({
          solicitudId: idDeRuta(route.params.solicitudId),
          back: () => router.push({ name: rutaBase })
        })
      },
      {
        path: 'notas',
        name: rutaBase + '-notas',
        component: () => import('@/views/solicitudes/[id]/notas.vue'),
        props: route => ({
          solicitudId: idDeRuta(route.params.solicitudId),
          back: () => router.push({ name: rutaBase })
        })
      }
    ]
  }
}

const routesAuth: RouteRecordRaw[] = [
  {
    path: '/auth',
    name: 'auth',
    component: () => import('../views/auth/index.vue'),
    children: [
      {
        path: 'login',
        name: 'auth-login',
        component: () => import('@/views/auth/login.vue'),
        meta: { logout: true },
        props: route => ({
          next: () => router.push(textoDeQuery(route.query.next) || '/home')
        })
      },
      {
        path: 'impersonate',
        name: 'auth-impersonate',
        component: () => import('@/views/auth/impersonate.vue'),
        meta: { requiresAuth: true }
      },
      {
        path: 'logout',
        name: 'auth-logout',
        component: () => import('@/views/auth/logout.vue'),
        meta: { logout: true }
      },
      {
        path: 'expired',
        name: 'auth-expired',
        component: () => import('@/views/auth/expired.vue'),
        meta: { logout: true },
        beforeEnter: (to, from) => replaceQuery(to, 'next', from ? from.fullPath : '/'),
        props: route => ({
          next: () => router.push(textoDeQuery(route.query.next))
        }),
      }
    ]
  }
]

const routesSolicitudes: RouteRecordRaw[] = [
  {
    path: '/solicitudes',
    redirect: folderDefault,
    children: [
      {
        path: ':tray/:state',
        name: 'solicitudes',
        component: () => import('@/views/solicitudes/index.vue'),
        meta: { requiresAuth: true, saveFolder: true },
        props: route => ({
          tray: route.params.tray,
          state: route.params.state,
          linkCrear: { name: 'solicitudes-crear' },
          solicitudId: route.params.solicitudId ? idDeRuta(route.params.solicitudId) : undefined,
          linkSolicitud: (solicitudId) => ({
            name: 'solicitudes-solicitud',
            params: { solicitudId }
          }),
          setSolicitudId: (solicitudId) => solicitudId && router.push({
            name: 'solicitudes-solicitud',
            params: { solicitudId }
          }),
        }),
        children: [
          {
            path: 'crear',
            name: 'solicitudes-crear',
            component: () => import('@/views/solicitudes/crear.vue'),
            props: () => ({
              back: () => router.push({ name: 'solicitudes' })
            })
          },
          rutasSolicitud('solicitudes-solicitud', 'solicitudes')
        ]
      }
    ]
  }
]

