import axios from 'axios'
import {
  NetworkError,
  AuthenticationError,
  AuthorizationError,
  NotFoundError,
  ValidationError,
  ServerError,
  ApiError
} from './errors'
import mitt from 'mitt'
import { shallowRef } from 'vue'
import { finalizarPeticion, iniciarPeticion } from '@/composables/useActividadRed'

// Importar los mensajes externalizados
import { ERROR_MESSAGES } from '@/constants/errorMessages'

export const events = mitt()

const notify = (type, message) => events.emit('error', { message, type })

const LOGIN_PATH = '/auth/login'

const esRutaLogin = (url?: string) => {
  const path = url?.split('?')[0] ?? ''
  return path.endsWith(LOGIN_PATH)
}

export const initAxiosInterceptors = () => {
  // No inyectamos el router aquA-: solo registramos el interceptor.
}

export const api = axios.create({
  withCredentials: true,
  baseURL: import.meta.env.VITE_API_URL,
  timeout: 120000,
  headers: {
    'X-Requested-With': 'XMLHttpRequest'
  },
  paramsSerializer: {
    indexes: null
  }
})

export const lastServerAccess = shallowRef(new Date())
const touchLastServerAccess = () => lastServerAccess.value = new Date()

// Cada peticiA3n que sale se contabiliza para que los indicadores globales
// (por ejemplo, la barra de progreso superior) sepan cuA�ndo hay trabajo en
// curso, sin que las vistas tengan que coordinarse entre sA-.
api.interceptors.request.use(
  config => {
    iniciarPeticion()
    return config
  },
  error => Promise.reject(error)
)

api.interceptors.response.use(
  response => {
    finalizarPeticion()
    touchLastServerAccess()
    return response
  },
  error => {
    finalizarPeticion()
    if (axios.isCancel(error)) throw error
    if (error instanceof ApiError) throw error

    if (!error.response) {
      notify('network', ERROR_MESSAGES.network)
      throw new NetworkError('Sin conexiA3n o servidor inaccesible.', error)
    }

    const { status, data, headers, config } = error.response
    const isHtml = headers['content-type']?.includes('text/html') ||
      (typeof data === 'string' && data.trim().startsWith('<'))

    let message = config?.url ? `Error en ${config.url}` : 'Error del servidor'
    if (!isHtml && data?.message) message = data.message
    else if (isHtml) message = ERROR_MESSAGES.htmlResponse

    switch (status) {
      case 401: {
        const esLogin = esRutaLogin(config?.url)
        const esIntentoLogin = esLogin && config?.method?.toLowerCase() === 'post'

        // El login fallido se muestra inline en el formulario, no como toast global.
        // El chequeo de sesiA3n (GET /auth/login) tampoco necesita toast.
        if (!esLogin) notify('client', ERROR_MESSAGES.unauthorized)

        // En el intento de login no se redirige: ya estamos en la pantalla de login.
        if (!esIntentoLogin) events.emit('unauthorized', { next: config?.url })

        throw new AuthenticationError(message, error)
      }

      case 403:
        notify('client', ERROR_MESSAGES.forbidden)
        throw new AuthorizationError(message, error)

      case 404:
        notify('client', ERROR_MESSAGES.notFound)
        throw new NotFoundError(message, error)

      case 422:
        throw new ValidationError(message, data, error)

      case 500:
      case 502:
      case 503:
      case 504:
        notify('server', ERROR_MESSAGES.server)
        throw new ServerError(ERROR_MESSAGES.internalServer, error)

      default:
        if (error.code === 'ECONNABORTED') {
          notify('network', ERROR_MESSAGES.timeout)
        } else if (error.message === 'Network Error') {
          notify('network', ERROR_MESSAGES.connection)
        } else {
          notify('unknown', ERROR_MESSAGES.unknown)
        }
        throw new ApiError(message, status, data, error)
    }
  }
)
=== ERRORS ===
import type { ErroresDeValidacion } from '@/types/api'

export class ApiError extends Error {
  statusCode: number | null
  data: unknown
  originalError: unknown

  constructor(message: string, statusCode: number | null, data: unknown = null, originalError: unknown = null) {
    super(message)
    this.name = 'ApiError'
    this.statusCode = statusCode
    this.data = data
    this.originalError = originalError
  }
}

export class NetworkError extends ApiError {
  constructor(message, originalError) {
    super(message, null, null, originalError)
    this.name = 'NetworkError'
  }
}

export class AuthenticationError extends ApiError {
  constructor(message, originalError) {
    super(message, 401, null, originalError)
    this.name = 'AuthenticationError'
  }
}

export class AuthorizationError extends ApiError {
  constructor(message, originalError) {
    super(message, 403, null, originalError)
    this.name = 'AuthorizationError'
  }
}

export class NotFoundError extends ApiError {
  constructor(message, originalError) {
    super(message, 404, null, originalError)
    this.name = 'NotFoundError'
  }
}

export class ValidationError extends ApiError {
  errors: ErroresDeValidacion

  constructor(message: string, data: unknown, originalError: unknown) {
    super(message, 422, data, originalError)
    this.name = 'ValidationError'
    // Normaliza estructuras comunes: { errors: { field: ["msg"] } } o { field: ["msg"] }
    const payload = data as { errors?: ErroresDeValidacion } | null
    this.errors = payload?.errors || (data as ErroresDeValidacion)
  }
}

export class ServerError extends ApiError {
  constructor(message: string, originalError: unknown) {
    super(message, 500, null, originalError)
    this.name = 'ServerError'
  }
}

// Type guards para uso seguro en TypeScript/JS
export const isApiError = (err: unknown): err is ApiError => err instanceof ApiError
export const isNetworkError = (err: unknown): err is NetworkError => err instanceof NetworkError
export const isValidationError = (err: unknown): err is ValidationError => err instanceof ValidationError

