import { ref, computed, watchEffect } from 'vue'
import { defineStore } from 'pinia'
import type { EstadoId, EstadoLista, Periodo, SolicitudesParams, Tray } from '@/types/api'

export const useSolicitudesFiltro = defineStore('solicitudes-filtro', () => {
  const tray = ref<Tray>() // Filtro base - requerido, va en la ruta, resetea filtros complementarios
  const state = ref<EstadoLista>() // Filtro base - requerido, va en la ruta, resetea filtros complementarios
  const status = ref<EstadoId>() // Filtro complementario
  const period = ref<Periodo>() // Filtro complementario
  const search = ref<string>() // Filtro complementario de search (toma valor si search y tray)

  const search_in = computed(() => search.value && tray.value
    ? ['codigo', 'objetivo', tray.value === 'recibidas' ? 'origen' : 'destino']
    : undefined)

  const filtro = computed<SolicitudesParams | undefined>(() => {
    if (tray.value === undefined || state.value === undefined) return undefined
    return {
      tray: tray.value,
      state: state.value,
      ...status.value ? { status: status.value } : {},
      ...period.value ? { period: period.value } : {},
      ...search.value ? { search: search.value } : {},
      ...search_in.value ? { search_in: search_in.value } : {},
    }
  })

  watchEffect(() => period.value = state.value === 'terminadas' ? 1 : undefined)

  const isFiltered = computed(() => Boolean(filtro.value && Object.keys(filtro.value).length > 2))

  const setFiltroBase = (newTray: Tray, newState: EstadoLista) => {
    // Si ya existA-a un filtro base previo (no es undefined), es un cambio de contexto real -> Resetear
    if (tray.value !== undefined || state.value !== undefined) {
      // Y ademA�s, si los valores son realmente distintos
      if (tray.value !== newTray || state.value !== newState) {
        resetComplementarios()
      }
    }
    tray.value = newTray
    state.value = newState
  }

  const resetComplementarios = () => {
    status.value = undefined
    period.value = state.value === 'terminadas' ? 1 : undefined
    search.value = undefined
  }

  return {
    tray,
    state,
    status,
    period,
    search,
    search_in,
    filtro,
    isFiltered,
    setFiltroBase
  }
}, {
  persist: {
    storage: sessionStorage, // Solo vive en la sesiA3n actual
    pick: ['status', 'period', 'search']
  }
})
import { useQuery, defineQuery, useQueryCache } from '@pinia/colada'
import { useSolicitudesFiltro } from './useSolicitudesFiltro'
import { useIntervalFn } from '@vueuse/core'
import { queryKeys } from '@/lib/query-keys'
import { solicitudesApi as api } from '@/api/solicitudes'
import type { SolicitudesListaResponse } from '@/types/api'
import { ref, computed, toRefs } from 'vue'

const STALE_TIME = 1000 * 60 * 5
const ESTADOS_PENDIENTES = ['Solicitado', 'En proceso', 'En evaluaciA3n'] as const

export const useSolicitudesQuery = defineQuery(() => {
  const queryCache = useQueryCache()

  const { filtro: params, isFiltered } = toRefs(useSolicitudesFiltro())

  const currentKey = computed(() => queryKeys.solicitudes.lista(params.value))

  const { data, isPending, isLoading, refresh, refetch } = useQuery<SolicitudesListaResponse>({
    key: currentKey,
    query: () => api.getAll(params.value),
    enabled: () => Boolean(params.value),
    staleTime: STALE_TIME,
    placeholderData: (previousData) => previousData,
  })

  const now = ref(Date.now())
  useIntervalFn(() => (now.value = Date.now()), 30_000)

  const isStale = computed(() => {
    const entry = queryCache.get(currentKey.value)
    if (!entry || entry.state.value.status !== 'success') return false
    return now.value >= entry.when + STALE_TIME
  })

  const conteoEstados = computed(() => {
    if (params.value?.state !== 'pendientes') return []
    const counts: Record<string, number> = {}
    for (const item of data.value?.data ?? []) {
      const estado = item?.[3]
      if (estado) counts[estado] = (counts[estado] ?? 0) + 1
    }
    return ESTADOS_PENDIENTES.map(estado => ({ estado, cantidad: counts[estado] ?? 0 }))
  })

  return {
    solicitudes: computed(() => data.value?.data),
    total: computed(() => data.value?.meta.total),
    isPending,
    isLoading,
    isStale,
    isFiltered,
    refresh,
    refetch,
    conteoEstados
  }
})
import { useQuery } from '@pinia/colada'
