import type { TiposParams } from '@/types/api'
import { computed, ref, watch } from 'vue'

const LIMIT_DEFAULT = 10
const LIMITS = [10, 25, 50, 100]

/**
 * Estado de la lista de tipos del admin: filtros + paginaciA3n del servidor.
 *
 * Es el estado local de la interfaz (no un store): se crea al montar la lista,
 * de modo que montar otra lista no lo comparte ni lo pisa.
 */
export function useTiposLista() {
  const { search, nombre, descripcion, uso, filtro, isFiltered, reset: resetFiltro } = useTiposFiltro()

  // PaginaciA3n (la resuelve el servidor)
  const page = ref(1)
  const limit = ref(LIMIT_DEFAULT)

  // Al cambiar un filtro se vuelve a la primera pA�gina. `sync` para que la
  // pA�gina ya estAc actualizada cuando se recalcule la clave de la consulta
  // (evita una peticiA3n con la pA�gina anterior).
  watch(filtro, () => (page.value = 1), { flush: 'sync' })

  // Filtros + paginaciA3n: es lo que espera el API (`page`, `limit`)
  const params = computed<TiposParams>(() => ({
    ...filtro.value,
    page: page.value,
    limit: limit.value,
  }))

  const { tipos, meta, isPending, isLoading } = useTiposQuery(params)

  const total = computed(() => meta.value?.total ?? 0)

  const reset = () => {
    resetFiltro()
    page.value = 1
  }

  return {
    nombre,
    descripcion,
    uso,
    search,
    isFiltered,
    page,
    limit,
    limits: LIMITS,
    tipos,
    isPending,
    isLoading,
    total,
    reset,
  }
}
