import { useMutation, useQueryCache } from '@pinia/colada'
import { queryKeys } from '@/lib/query-keys'
import { notasApi as api } from '@/api/notas'
import type { NotaCreate } from '@/types/models'

export function useNotaCreate() {
  const queryCache = useQueryCache()

  return useMutation<number, NotaCreate>({
    mutation: (newData) => api.create(newData),

    onMutate: () => {
      queryCache.cancelQueries({ key: queryKeys.notas.listas() })
      queryCache.cancelQueries({ key: queryKeys.solicitudes.detalles() })
    },

    onSuccess: () => {
      queryCache.invalidateQueries({ key: queryKeys.notas.listas() })
      queryCache.invalidateQueries({ key: queryKeys.solicitudes.detalles() })
    }
  })
}
import { useQuery } from '@pinia/colada'
import { queryKeys } from '@/lib/query-keys'
import { notasApi as api } from '@/api/notas'
import { formatHM, formatDate } from '@/composables/useDates'
import type { Id } from '@/types/api'
import type { Nota } from '@/types/models'
import { computed, toValue } from 'vue'

type NotaConHora = Nota & {
  hora: string,
}

export function useNotasQuery(solicitudId?: Id) {

  const { data: _data, isPending } = useQuery<Nota[]>({
    key: () => queryKeys.notas.lista({ solicitudId: toValue(solicitudId) }),
    query: () => api.getAll({ solicitudId: toValue(solicitudId) }),
    enabled: () => !!toValue(solicitudId),
  })

  const notas = computed(() => {
    const items = _data.value || []
    const out: Record<string, NotaConHora[]> = {}
    for (const it of items) {
      const key = formatDate(it.fecha) ?? ''
      if (!out[key]) out[key] = []
      out[key].push({ ...it, hora: formatHM(it.fecha) })
    }
    return out
  })

  return {
    notas,
    isPending,
  }
}
